module ApplicationHelper
  def inr(paise, **opts) = Money.format(paise, **opts)
  def inr0(paise) = Money.format(paise, decimals: false)
  def inr_compact(paise) = Money.compact(paise)
  def d(date) = date&.strftime("%d %b %Y")
  def dt(time) = time&.in_time_zone&.strftime("%d %b, %I:%M %p")
  def short_d(date) = date&.strftime("%d %b")

  def nav_link(label, path, icon:, match: nil, badge: nil)
    active = match ? request.path.match?(match) : current_page?(path)
    link_to path, class: ["nav-link", ("active" if active)] do
      safe_join([icon(icon, class: "size-4 #{active ? 'text-brand-600' : 'text-slate-400'}"), tag.span(label, class: "flex-1"),
                 (tag.span(badge, class: "rounded-full bg-rose-500 px-1.5 text-[10px] font-semibold text-white tnum") if badge.to_i.positive?)].compact)
    end
  end

  def status_badge(status)
    cls = case status.to_s
          when "posted", "paid", "cleared", "delivered", "settled", "replaced", "approved", "done", "sent", "credited", "read" then "badge-green"
          when "overdue", "cancelled", "bounced", "failed", "rejected", "written_off" then "badge-red"
          when "part-paid", "partial", "with_brand", "pending", "awaiting", "out", "draft", "queued" then "badge-amber"
          when "confirmed", "planned", "open", "unpaid" then "badge-blue"
          else "badge-gray"
          end
    tag.span(status.to_s.humanize, class: cls)
  end

  def channel_badge(channel)
    case channel
    when "whatsapp" then tag.span(safe_join([icon("whatsapp", class: "size-3"), "WhatsApp"]), class: "badge-wa")
    when "salesman" then tag.span("Salesman", class: "badge-violet")
    when "route" then tag.span("On route", class: "badge-violet")
    else tag.span("Counter", class: "badge-gray")
    end
  end

  def bucket_badge(bucket)
    cls = { "sellable" => "badge-green", "awaiting_claim" => "badge-amber", "with_brand" => "badge-blue", "written_off" => "badge-red" }[bucket]
    tag.span(StockMovement::BUCKET_LABELS[bucket], class: cls)
  end

  def balance_tag(paise)
    cls = paise.positive? ? "text-slate-900" : paise.negative? ? "text-emerald-700" : "text-slate-400"
    tag.span(paise.negative? ? "#{inr(-paise)} Cr" : inr(paise), class: "tnum font-medium #{cls}")
  end

  def page_header(title, sub = nil, &block)
    tag.div(class: "mb-6 flex flex-wrap items-end justify-between gap-3") do
      safe_join([tag.div { safe_join([tag.h1(title, class: "page-title"), (tag.p(sub, class: "page-sub mt-0.5") if sub)].compact) },
                 (tag.div(class: "flex flex-wrap items-center gap-2", &block) if block)].compact)
    end
  end

  def stat_tile(label, value, sub: nil, tone: nil, href: nil)
    body = safe_join([tag.div(label, class: "stat-label"), tag.div(value, class: "stat-value #{tone}"),
                      (tag.div(sub, class: "mt-1 text-xs text-slate-500") if sub)].compact)
    href ? link_to(body, href, class: "stat block hover:ring-2 hover:ring-brand-500/20 transition") : tag.div(body, class: "stat")
  end

  def empty_state(text, &block)
    tag.div(class: "empty") { safe_join([tag.p(text), (capture(&block) if block)].compact) }
  end

  def wa_link(phone, text = nil)
    "https://wa.me/#{phone}#{"?text=#{ERB::Util.url_encode(text)}" if text}"
  end

